/*
 * HMCLNoIPCheck - compile-time stub.
 *
 * `JsonSerializable` has RetentionPolicy.SOURCE, so the class is removed by HMCL's shadowJar
 * minimizer even though RegionUtils is annotated with it. This stub only exists so that the
 * patched RegionUtils compiles against the shipped jar; it never ends up in the patch jar and
 * leaves no trace in the generated bytecode.
 */
package org.jackhuang.hmcl.util.gson;

import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Documented
@Retention(RetentionPolicy.SOURCE)
@Target(ElementType.TYPE)
public @interface JsonSerializable {
}
